  return [...TIME_ZONES]
    .sort((a, b) => offsetMinutes(a.id, date) - offsetMinutes(b.id, date))
    .map(({ id, city }) => {
      const offset = formatTimeZoneOffset(id, date);
      const label = offset ? `(${offset}) ${city}` : city;
      return { value: id, content: label, text: `${label} ${id}` };
    });
}

