(npx vite --port 5173 --strictPort > /tmp/vite.log 2>&1 &) ; cat > /tmp/pw/shot.mjs <<'EOF'
import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.type() + ': ' + m.text()); });

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle' });
await page.waitForSelector('text=Настройки профиля');
await page.screenshot({ path: '/tmp/pw/01-initial.png', fullPage: true });

// Validation: clear name, submit
const name = page.locator('#profile-name');
await name.fill('');
await page.locator('#profile-email').fill('bad-email');
await page.getByRole('button', { name: 'Сохранить' }).click();
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/pw/02-errors.png', fullPage: true });

// Fix, toggle switch, checkbox, upload avatar, open timezone select
await name.fill('Анна Смирнова');
await page.locator('#profile-email').fill('anna@example.com');
await page.getByRole('switch').click();
await page.getByText('Дайджест за неделю').click();
// 1x1 png
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg==', 'base64');
await page.locator('input[type=file]').setInputFiles({ name: 'a.png', mimeType: 'image/png', buffer: png });
await page.waitForTimeout(200);
await page.locator('#profile-timezone').click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/pw/03-dirty-tz-open.png', fullPage: true });
await page.keyboard.press('Escape');

// Save -> toast
await page.getByRole('button', { name: 'Сохранить' }).click();
await page.waitForSelector('text=Настройки сохранены', { timeout: 5000 });
await page.screenshot({ path: '/tmp/pw/04-saved.png', fullPage: true });

// Mobile
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/pw/05-mobile.png', fullPage: true });

writeFileSync('/tmp/pw/errors.txt', errors.join('\n') || '(no console errors)');
await browser.close();
EOF
sleep 3; tail -5 /tmp/vite.log

